      "chunk_id": "text_10",
      "quote": "Clinical manifestations, risk factors, and maternal and perinatal outcomes of coronavirus disease 2019 in pregnancy: living systematic review and meta-analysis",
      "reason": "The title explicitly includes the phrase \"living systematic review and meta-analysis\"."
    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "text_10",
      "quote": "Clinical manifestations, risk factors, and maternal and perinatal outcomes of coronavirus disease 2019 in pregnancy: living systematic review and meta-analysis",
      "reason": "The title identifies the population (\"in pregnancy\") and the exposure/condition (\"coronavirus disease 2019\"), as well as the outcomes being studied (\"Clinical manifestations, risk factors, and maternal and perinatal outcomes\")."
    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "PRESENT",
      "chunk_id": "text_10",
      "quote": "Clinical manifestations, risk factors, and maternal and perinatal outcomes of coronavirus disease 2019 in pregnancy: living systematic review and meta-analysis",
