{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_12",
      "quote": "Since the first report (December 2019) of the novel coronavirus disease 2019 (covid-19) caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), the number of confirmed cases and associated mortality and morbidity have increased rapidly. 12 Pregnant women are considered a high risk group because of concerns about the effect of covid-19 on them during and after pregnancy, and on their neonates. 3",
      "reason": "The introduction describes the rapid increase in COVID-19 cases and the specific concerns regarding the impact on pregnant women and neonates, establishing the current state of knowledge and uncertainties."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_12",
      "quote": "Quantification of the rates of covid-19, its risk factors, clinical manifestations, and outcomes is key to planning clinical maternal care and management in an evolving pandemic scenario.",
      "reason": "The text explicitly states the need for the review to quantify outcomes to assist in planning clinical maternal care and management."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "This version is update 2 of the original article published on 1 September 2020 ( BMJ 2020;370:m3320), and previous updates can be found as data supplements",
      "reason": "The manuscript identifies itself as an update to a previous version of the same systematic review and provides the citation."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a systematic review of observational cohort studies regarding clinical manifestations and outcomes, not an intervention review."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a systematic review of observational cohort studies, not a review of complex interventions."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_10",
      "quote": "Our systematic review is based on a prospectively registered protocol (PROSPERO CRD42020178076; registered 22 April 2020) 19 to evaluate a series of research questions on covid-19 during and after pregnancy. We report our findings on the rates, clinical manifestations, risk factors, and maternal and perinatal outcomes in women with covid-19",
      "reason": "The review explicitly states its objectives: to evaluate research questions regarding rates, clinical manifestations, risk factors, and maternal and perinatal outcomes in women with COVID-19 during and after pregnancy."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "PRESENT",
      "chunk_id": "text_15",
      "quote": "We included studies that compared covid-19 rates, clinical manifestations (symptoms, laboratory and radiological results), risk factors, and associated mortality and morbidity between pregnant and recently pregnant and non-pregnant women of reproductive age, and those that compared maternal and perinatal outcomes in pregnant women with and without covid-19.",
      "reason": "The review includes comparative analyses (e.g., pregnant vs. non-pregnant, pregnant with vs. without COVID-19), and the text explicitly defines these comparisons, satisfying the requirement for stating planned comparisons."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_15",
      "quote": "We included studies that compared covid-19 rates, clinical manifestations (symptoms, laboratory and radiological results), risk factors, and associated mortality and morbidity between pregnant and recently pregnant and non-pregnant women of reproductive age, and those that compared maternal and perinatal outcomes in pregnant women with and without covid-19. ... Studies on noncomparative cohorts with a minimum of 10 participants were included if they reported on the rates and clinical manifestations of covid-19 and relevant outcomes in pregnant and recently pregnant women. We defined cohort studies as those that sampled participants on the basis of exposure, followed-up participants over time, and ascertained the outcomes.",
      "reason": "The manuscript specifies the eligible study designs (comparative and non-comparative cohort studies), the population (pregnant and recently pregnant women), and the outcomes/characteristics of interest."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_13",
      "quote": "No language restrictions were applied.",
      "reason": "The manuscript explicitly states that no language restrictions were applied. While dissemination year and publication status are not explicitly detailed as exclusion criteria, the inclusion of preprint servers and the nature of the living review implies broad inclusion, and the lack of language restriction is a key component of report characteristics."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The provided text does not indicate that the review had to distinguish between exclusion due to outcomes not being measured versus not being reported; this is a specific methodological nuance not addressed in the provided evidence."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_16",
      "quote": "We undertook subgroup analysis by country status (high income v low and middle income), sampling frame (universal, risk based, and symptom based testing, including not reported), and risk status of women in the studies (high, low, any). Sensitivity analysis was performed by restricting the analysis to women with confirmed covid-19, study quality (high, low), and population (unselected, selected).",
      "reason": "The manuscript specifies the groups used for synthesis (subgroup and sensitivity analyses) and links them to the review objectives (e.g., country status, sampling frame, risk status, study quality)."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "callout_0",
      "quote": "To minimise risk of bias we restricted our meta-analysis to cohort studies, and we reported the quality of the included studies.",
      "reason": "The manuscript provides a rationale for restricting the meta-analysis to cohort studies (to minimize risk of bias)."
    }
  ],
  "confidence": 95
}

