      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not report performing backward or forward citation searching as a specific method, only reference list checking."
    },
    {
      "element_id": "prisma_2020_6_e9",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not report consulting specific journals or conference proceedings as a distinct search source beyond the general database searches."
    }
  ],
  "confidence": 100
